<?php require __DIR__.'/../app/bootstrap.php';admin_required();$products=db()->query('SELECT p.*,c.name category_name FROM products p LEFT JOIN categories c ON c.id=p.category_id ORDER BY p.created_at DESC')->fetchAll();?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Products — NEXT TECH Admin</title><link rel="stylesheet" href="<?=e(url('assets/css/style.css'))?>"></head><body class="admin-body"><aside class="admin-sidebar"><a class="wordmark" href="<?=e(url('admin/index.php'))?>"><span>NEXT</span> <b>TECH</b></a><a href="<?=e(url('admin/index.php'))?>">Dashboard</a><a class="active" href="<?=e(url('admin/products.php'))?>">Products</a><a href="<?=e(url('admin/categories.php'))?>">Categories</a><a href="<?=e(url('admin/orders.php'))?>">Orders</a><a href="<?=e(url('index.php'))?>">View Store</a><a href="<?=e(url('admin/logout.php'))?>">Logout</a></aside><main class="admin-main"><div class="admin-top"><h1>Products</h1><a class="btn btn-primary" href="<?=e(url('admin/product-form.php'))?>">＋ Add Product</a></div><div class="admin-panel table-wrap"><table><thead><tr><th>Product</th><th>Category</th><th>Price</th><th>Stock</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($products as $p): ?><tr><td><?=e($p['name'])?></td><td><?=e($p['category_name']??'—')?></td><td><?=money($p['price'])?></td><td><?=(int)$p['stock']?></td><td><?=e($p['status'])?></td><td><a href="<?=e(url('admin/product-form.php?id='.(int)$p['id']))?>">Edit</a><form method="post" action="<?=e(url('admin/delete-product.php'))?>" style="display:inline" onsubmit="return confirm('Delete this product?')"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=(int)$p['id']?>"><button class="text-link" style="border:0;background:none;cursor:pointer">Delete</button></form></td></tr><?php endforeach; ?></tbody></table><?php if(!$products): ?><p>No products added yet.</p><?php endif; ?></div></main></body></html>
